selector_to_html = {"a[href=\"#pyskyfire.thermo.eos.Incompressible.speed_of_sound\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible.speed_of_sound\">\n<span class=\"sig-name descname\"><span class=\"pre\">speed_of_sound</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">state</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Speed of sound in <code class=\"docutils literal notranslate\"><span class=\"pre\">state</span></code> [m s\u207b\u00b9].</p></dd>", "a[href=\"#pyskyfire.thermo.eos.Incompressible._need_cp\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible._need_cp\">\n<span class=\"sig-name descname\"><span class=\"pre\">_need_cp</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">what</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.thermo.eos.Incompressible.__repr__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible.__repr__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__repr__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.thermo.eos.Incompressible._state\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible._state\">\n<span class=\"sig-name descname\"><span class=\"pre\">_state</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.thermo.eos.Incompressible.isentropic\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible.isentropic\">\n<span class=\"sig-name descname\"><span class=\"pre\">isentropic</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">state</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The state reached from <code class=\"docutils literal notranslate\"><span class=\"pre\">state</span></code> by an isentropic process to <code class=\"docutils literal notranslate\"><span class=\"pre\">p</span></code>.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.Incompressible.state_ph\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible.state_ph\">\n<span class=\"sig-name descname\"><span class=\"pre\">state_ph</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The state at pressure <code class=\"docutils literal notranslate\"><span class=\"pre\">p</span></code> and specific enthalpy <code class=\"docutils literal notranslate\"><span class=\"pre\">h</span></code>.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.Incompressible.state_pT\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible.state_pT\">\n<span class=\"sig-name descname\"><span class=\"pre\">state_pT</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The state at pressure <code class=\"docutils literal notranslate\"><span class=\"pre\">p</span></code> and temperature <code class=\"docutils literal notranslate\"><span class=\"pre\">T</span></code>.</p></dd>", "a[href=\"#pyskyfire-thermo-eos-incompressible\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.thermo.eos.Incompressible<a class=\"headerlink\" href=\"#pyskyfire-thermo-eos-incompressible\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.thermo.eos.Incompressible.entropy\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible.entropy\">\n<span class=\"sig-name descname\"><span class=\"pre\">entropy</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">state</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Specific entropy of <code class=\"docutils literal notranslate\"><span class=\"pre\">state</span></code> [J kg\u207b\u00b9 K\u207b\u00b9], on this EOS\u2019s own datum.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.Incompressible\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.eos.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Incompressible</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cp</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">EquationOfState</span></code></p><p>A fluid of constant density.</p><p>Enthalpy is <code class=\"docutils literal notranslate\"><span class=\"pre\">cp*T</span> <span class=\"pre\">+</span> <span class=\"pre\">p/rho</span></code>. With constant density, an isentropic\nprocess is also isothermal, so it moves only the <code class=\"docutils literal notranslate\"><span class=\"pre\">p/rho</span></code> term. The\nisentropic head between two pressures is then <code class=\"docutils literal notranslate\"><span class=\"pre\">\u0394p/rho</span></code> exactly: the\nfamiliar pump head.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">cp</span></code> is optional. Without it temperature is carried through isentropic\nprocesses but cannot be recovered from an enthalpy, so <a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.Incompressible.state_ph\" title=\"pyskyfire.thermo.eos.Incompressible.state_ph\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">state_ph()</span></code></a>\nreports it as NaN, and there is no entropy: <a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.Incompressible.entropy\" title=\"pyskyfire.thermo.eos.Incompressible.entropy\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">entropy()</span></code></a> and\n<a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.Incompressible.state_hs\" title=\"pyskyfire.thermo.eos.Incompressible.state_hs\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">state_hs()</span></code></a> need <code class=\"docutils literal notranslate\"><span class=\"pre\">cp</span></code>. Entropy is then <code class=\"docutils literal notranslate\"><span class=\"pre\">cp*ln(T)</span></code>, datum 1 K.\nSound is infinitely fast in an incompressible fluid.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.Incompressible.state_hs\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible.state_hs\">\n<span class=\"sig-name descname\"><span class=\"pre\">state_hs</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">s</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The state with specific enthalpy <code class=\"docutils literal notranslate\"><span class=\"pre\">h</span></code> and specific entropy <code class=\"docutils literal notranslate\"><span class=\"pre\">s</span></code>.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
